a98fcdac-6a35-4c76-b048-c49611f2c0d8	a9385480-d886-4ab8-99e2-673e8db8ae6b	#### 1. 规则引擎实现\n```javascript\n// assessmentEngine.js\nclass AssessmentEngine {\n  constructor(vectorService, dashScopeService) {\n    this.vectorService = vectorService;\n    this.dashScope = dashScopeService;\n  }\n  \n  async evaluate(teachingPlan, slideshow, scoringRules) {\n    const results = {\n      totalScore: 100,\n      deductions: [],\n      detailedScores: {},\n      suggestions: []\n    };\n    \n    // 执行各项检查\n    for (const rule of scoringRules.rules) {\n      const ruleResult = await this.executeRule(rule, teachingPlan, slideshow);\n      results.detailedScores[rule.ruleId] = ruleResult;\n      \n      if (ruleResult.deduction > 0) {\n        results.totalScore -= ruleResult.deduction;\n        results.deductions.push({\n          rule: rule.criteria,\n          points: ruleResult.deduction,\n          reason: ruleResult.reason\n        });\n      }\n    }\n    \n    // 生成改进建议\n    results.suggestions = await this.generateSuggestions(results.deductions);\n    \n    return results;\n  }\n  \n  async executeRule(rule, teachingPlan, slideshow) {\n    switch (rule.checkType) {\n      case 'completeness_check':\n        return await this.checkCompleteness(rule, teachingPlan);\n      case 'semantic_similarity_check':\n        return await this.checkSemanticSimilarity(rule, teachingPlan, slideshow);\n      default:\n        return { score: 0, deduction: 0, reason: 'Unknown rule type' };\n    }\n  }\n}\n```	21	null	\N	{"strategy": "paragraph"}	2025-09-28 08:00:21.247116+08	2025-09-28 16:00:23.044821+08	[0.06734979152679443, -0.030362611636519432, -0.005313456989824772, -0.07452641427516937, -0.03836730122566223, 0.06265739351511002, -0.05962112918496132, -0.014077210798859596, 0.005278954282402992, -0.03063863515853882, -0.056308843195438385, -0.06845388561487198, 0.05299656093120575, -0.0038125780411064625, -0.026636291295289993, 0.09053578972816467, -0.07949484139680862, -0.02290997